    public static List<Entry> all(){return Collections.unmodifiableList(ENTRIES);}
    public static List<String> groups(){
        LinkedHashSet<String> groups=new LinkedHashSet<>();
        for(Entry e:ENTRIES)groups.add(e.category);
        return Collections.unmodifiableList(new ArrayList<>(groups));
    }
    public static int canonicalCount(){
        int n=0; for(Entry e:ENTRIES)if(SKYRIM.equals(e.origin)||DAWNGUARD.equals(e.origin)||DRAGONBORN.equals(e.origin))n++;
        return n;
    }
    public static int gameCount(){ int n=0;for(Entry e:ENTRIES)if(GAME.equals(e.origin))n++;return n; }
    public static List<Entry> filter(String query,String category){
        String q=key(query);
        // Search by historical creature names must keep working after localization.
        if(ALIASES.containsKey(q))q=ALIASES.get(q);
        ArrayList<Entry> out=new ArrayList<>();
        for(Entry e:ENTRIES){
            if(category!=null&&!ALL.equals(category)&&!category.equals(e.category))continue;
            if(q.isEmpty()||key(e.name+" "+e.id+" "+e.category+" "+e.origin+" "+e.habitat+" "+e.appearance+
                " "+e.behavior+" "+e.abilities+" "+e.loot+" "+e.legend+" "+e.type).contains(q))out.add(e);
        }
        return out;
    }
    public static Entry find(String raw){
        String k=key(raw);
        if(ALIASES.containsKey(k))k=ALIASES.get(k);
        return BY_NAME.get(k);
    }
